    #[test]
    fn pp_admission_pp4_preserves_step_tp_kv_aggregation() {
        use memra_engine::hybrid::StepTpKvDeviceAdmission;

        let stages = pp_stage_admissions(&[10, 20, 30, 40], &[0; 4], 5, &[0, 14, 14, 14]);
        let devices = [0, 1, 2, 3];
        let request = [
            StepTpKvDeviceAdmission {
                device: 1,
                bytes: 11,
            },
            StepTpKvDeviceAdmission {
                device: 4,
                bytes: 13,
            },
        ];
        let pending = [
            StepTpKvDeviceAdmission {
                device: 1,
                bytes: 17,
            },
            StepTpKvDeviceAdmission {
                device: 4,
                bytes: 19,
            },
        ];
        let requirements = parallel_device_requirements(
            0,
            0,
            5,
            Some((&devices, &stages)),
            &request,
            &pending,
            &[],
        );

        assert_eq!(requirements.len(), 5);
        assert_eq!(requirements[1].device, 1);
        assert_eq!(requirements[1].session_bytes, 20);
        assert_eq!(requirements[1].state_bytes, 11);
        assert_eq!(requirements[1].pending_state_bytes, 17);
        assert_eq!(requirements[1].reserve_bytes, 5);
        assert_eq!(requirements[1].boundary_bytes, 14);
        assert_eq!(requirements[1].required(), 67);
        assert_eq!(requirements[4].device, 4);
        assert_eq!(requirements[4].session_bytes, 0);
        assert_eq!(requirements[4].state_bytes, 13);
        assert_eq!(requirements[4].pending_state_bytes, 19);
        assert_eq!(requirements[4].reserve_bytes, 5);
        assert_eq!(requirements[4].boundary_bytes, 0);
        assert_eq!(requirements[4].required(), 37);
    }

    #[test]
    fn pp_admission_arithmetic_saturates_and_serial_is_unchanged() {
        let stages = pp_stage_admissions(
            &[usize::MAX, 1, usize::MAX, 1],
            &[1; 4],
            1,
            &[0, usize::MAX, usize::MAX, usize::MAX],
        );
        let devices = pp_device_requirements(&[0, 1, 2, 3], &stages);

        assert!(
            devices
                .iter()
                .all(|requirement| requirement.required() == usize::MAX)
        );
        let repeated = pp_device_requirements(&[9, 9, 9, 9], &stages);
        assert_eq!(repeated.len(), 1);
        assert_eq!(repeated[0].required(), usize::MAX);
        assert_eq!(admission_required(usize::MAX, 1), usize::MAX);
        assert_eq!(
            admission_required(680 << 20, 680 << 20),
            (680 << 20) * 2,
            "the serial rollback keeps the previous cost + reserve equation",
        );
    }

    #[test]
    fn step_tp8_admission_charges_every_rank_and_outstanding_lazy_sidecars() {
        use memra_engine::{cache::swa_ring_rows, hybrid::StepTpKvDeviceAdmission};

        let ctx = 262_144usize;
        let global_attention_layers = (0..45).filter(|layer| layer % 4 == 0).count();
        let swa_layers = 45 - global_attention_layers;
        assert_eq!(global_attention_layers, 12);
        assert_eq!(swa_layers, 33);
        let bytes_per_rank_token = global_attention_layers * 232;
        let fixed_per_layer = 20;
        let global_bytes = global_attention_layers * (232 * ctx + fixed_per_layer);
        let swa_rows = swa_ring_rows(512, ctx);
        let swa_bytes = swa_layers * (232 * swa_rows + fixed_per_layer);
        let sidecar = global_bytes + swa_bytes;
        let request: Vec<_> = (0..8)
            .map(|device| StepTpKvDeviceAdmission {
                device,
                bytes: sidecar,
            })
            .collect();
        let pending: Vec<_> = (0..8)
            .map(|device| StepTpKvDeviceAdmission {
                device,
                bytes: sidecar,
            })
            .collect();
        let legacy = 83_520 * ctx;
        let reserve = 1_500 << 20;
        let requirements =
            parallel_device_requirements(0, legacy, reserve, None, &request, &pending, &[]);

        assert_eq!(requirements.len(), 8);
        assert_eq!(bytes_per_rank_token, 2_784);
        // 5_151 = window 512 + PRIME_CHUNK_MAX_TOKENS 4096 + SWA_REWIND_SLACK_ROWS 512 +
        // (SWA_VIEW_ALIGNMENT_ROWS - 1) 31. The literal was 4_639 (the pre-slack geometry)
        // and went stale when 04ff294bed sized the rewind headroom into the ring instead of
        // scavenging 32 rows from it; this admission test is the only pin on that number.
        assert_eq!(swa_rows, 5_151);
        assert_eq!(requirements[0].session_bytes, legacy);
        assert_eq!(requirements[0].state_bytes, sidecar);
        assert_eq!(requirements[0].pending_state_bytes, sidecar);
        assert_eq!(requirements[0].required(), legacy + sidecar * 2 + reserve);
        for peer in &requirements[1..] {
            assert_eq!(peer.session_bytes, 0);
            assert_eq!(peer.state_bytes, sidecar);
            assert_eq!(peer.pending_state_bytes, sidecar);
            assert_eq!(peer.reserve_bytes, reserve);
            assert_eq!(peer.required(), sidecar * 2 + reserve);
        }

        let mut devices: Vec<_> = requirements
            .iter()
            .copied()
            .map(|requirement| AdmissionDeviceHeadroom {
                free_bytes: requirement.required(),
                requirement,
                pool_cached_bytes: 0,
                pool_reserved_bytes: 0,
                pool_used_bytes: 0,
            })
            .collect();
        devices[7].free_bytes -= 1;
        assert!(
            !AdmissionHeadroom::Devices(devices).sufficient(0),
            "one byte of missing peer headroom must defer the whole TP8 request"
        );
    }

    #[test]
    fn glm_peer_pressure_includes_pending_state_and_recovers_after_refill() {
        use memra_engine::hybrid::StepTpKvDeviceAdmission;
        // Root KV is already in the primary estimate. A GLM peer additionally owns
        // recurrent state and its replicated latent KV, plus a transient workspace floor.
        let request = [StepTpKvDeviceAdmission {
            device: 23,
            bytes: 400,
        }];
        let pending = [StepTpKvDeviceAdmission {
            device: 23,
            bytes: 100,
        }];
        let required = parallel_device_requirements(0, 300, 50, None, &request, &pending, &[]);
        assert_eq!(required.len(), 2);
        assert_eq!(required[1].required(), 550);
        let mut peers = required
            .iter()
            .copied()
            .map(|requirement| AdmissionDeviceHeadroom {
                requirement,
                free_bytes: 1_000,
                pool_cached_bytes: 0,
                pool_reserved_bytes: 0,
                pool_used_bytes: 0,
            })
            .collect::<Vec<_>>();
        for _ in 0..3 {
            // Root has room while only the peer is one byte short.
            peers[1].free_bytes = 549;
            assert!(!AdmissionHeadroom::Devices(peers.clone()).sufficient(0));
            // A peer-only release makes the whole request admissible; no root release.
            peers[1].free_bytes += 1;
            assert!(AdmissionHeadroom::Devices(peers.clone()).sufficient(0));
        }
        let workspace = [StepTpKvDeviceAdmission {
            device: 23,
            bytes: 1_000,
        }];
        let long_prompt =
            parallel_device_requirements(0, 300, 50, None, &request, &pending, &workspace);
        assert_eq!(long_prompt[1].required(), 1_550);
        peers[1].requirement = long_prompt[1];
        peers[1].free_bytes = 550;
        assert!(
            !AdmissionHeadroom::Devices(peers.clone()).sufficient(0),
            "a peer fitting state alone must defer when prefill workspace does not fit"
        );
        peers[1].free_bytes = 1_550;
        assert!(AdmissionHeadroom::Devices(peers).sufficient(0));
        let materialized = [StepTpKvDeviceAdmission {
            device: 23,
            bytes: 0,
        }];
        let warm = parallel_device_requirements(0, 300, 50, None, &materialized, &[], &[]);
        assert_eq!(
            warm[1].required(),
            50,
            "warm peer still needs workspace headroom"
        );
    }

    #[test]
    fn admission_activation_residual_is_a_high_water_not_a_new_scalar() {
        let mut cost = AdmissionCostModel {
            plain_bytes_per_token: 4_096,
            spec_bytes_per_token: 6_144,
            plain_ring_bytes_per_token: 0,
            spec_ring_bytes_per_token: 0,
            ring_rows: 0,
            activation_bytes: 0,
            prefill: None,
            prime: None,
            transient_floor: None,
            pp_activation_bytes: [0; 4],
            last_logged: None,
        };
        let ctx_8k = 8_192;
        let linear_8k = cost.plain_bytes_per_token * ctx_8k;

        assert_eq!(
            cost.observe(linear_8k + 32_000_000, ctx_8k, false),
            Some(32_000_000)
        );
        assert_eq!(cost.observe(linear_8k + 8_000_000, ctx_8k, false), None);
        assert_eq!(
            cost.activation_bytes, 32_000_000,
            "the residual never moves down"
        );
        assert_eq!(
            cost.estimate(131_072, 131_072, false),
            cost.plain_bytes_per_token * 131_072 + 32_000_000,
            "an 8k observation contributes only its fixed residual to a later 128k request",
        );
    }

    #[test]
    fn admission_reclaim_selects_the_global_oldest_across_all_pools() {
        let now = std::time::Instant::now();
        let plain_key: PoolKey = ("model".into(), "plain-ns".into());
        let spec_key: PoolKey = ("model".into(), "spec-ns".into());
        let oldest = oldest_parked_candidate([
            ParkedCandidate {
                pool: ParkedPool::Plain,
                key: plain_key,
                index: 0,
                parked_at: now - std::time::Duration::from_secs(2),
            },
            ParkedCandidate {
                pool: ParkedPool::Spec,
                key: spec_key.clone(),
                index: 1,
                parked_at: now - std::time::Duration::from_secs(3),
            },
            ParkedCandidate {
                pool: ParkedPool::Plain,
                key: ("model".into(), "newer-ns".into()),
                index: 2,
                parked_at: now - std::time::Duration::from_secs(1),
            },
            ParkedCandidate {
                pool: ParkedPool::Dspark,
                key: ("model".into(), "dspark-ns".into()),
                index: 3,
                parked_at: now - std::time::Duration::from_secs(4),
            },
        ])
        .expect("a parked candidate exists");

        assert_eq!(oldest.pool, ParkedPool::Dspark);
        assert_eq!(oldest.key, ("model".into(), "dspark-ns".into()));
        assert_eq!(oldest.index, 3);
        assert!(oldest_parked_candidate(Vec::new()).is_none());
    }

    #[test]
    fn parked_entry_ceiling_bounds_salt_fanout_and_evicts_global_oldest() {
        const PER_NAMESPACE_CAP: usize = 2;
        const GLOBAL_CAP: usize = 5;
        const NAMESPACES: usize = 4;

        fn park(
            target: ParkedPool,
            key: PoolKey,
            entry: TestParkedEntry,
            reuse: &mut HashMap<PoolKey, Vec<TestParkedEntry>>,
            spec_reuse: &mut HashMap<PoolKey, Vec<TestParkedEntry>>,
            dspark_reuse: &mut HashMap<PoolKey, Vec<TestParkedEntry>>,
            metrics: &mut ReuseMetrics,
        ) {
            assert!(prepare_park(
                target,
                &key,
                reuse,
                spec_reuse,
                dspark_reuse,
                metrics,
                PER_NAMESPACE_CAP,
                GLOBAL_CAP,
            ));
            match target {
                ParkedPool::Plain => reuse.entry(key).or_default().push(entry),
                ParkedPool::Spec => spec_reuse.entry(key).or_default().push(entry),
                ParkedPool::Dspark => dspark_reuse.entry(key).or_default().push(entry),
            }
            assert!(parked_entry_count(reuse, spec_reuse, dspark_reuse) <= GLOBAL_CAP);
        }

        let now = std::time::Instant::now();
        let mut reuse = HashMap::new();
        let mut spec_reuse = HashMap::new();
        let mut dspark_reuse = HashMap::new();
        let mut metrics = ReuseMetrics::default();
        let mut next_id = 0u32;

        for namespace in 0..NAMESPACES {
            let target = match namespace % 3 {
                0 => ParkedPool::Plain,
                1 => ParkedPool::Spec,
                _ => ParkedPool::Dspark,
            };
            let key: PoolKey = ("model".into(), format!("salt-{namespace}"));
            for _ in 0..PER_NAMESPACE_CAP {
                park(
                    target,
                    key.clone(),
                    TestParkedEntry {
                        id: next_id,
                        parked_at: now + std::time::Duration::from_millis(next_id as u64),
                    },
                    &mut reuse,
                    &mut spec_reuse,
                    &mut dspark_reuse,
                    &mut metrics,
                );
                next_id += 1;
            }
        }

        let mut live_ids: Vec<u32> = reuse
            .values()
            .chain(spec_reuse.values())
            .chain(dspark_reuse.values())
            .flat_map(|pool| pool.iter().map(|entry| entry.id))
            .collect();
        live_ids.sort_unstable();
        assert_eq!(live_ids, vec![3, 4, 5, 6, 7]);
        assert_eq!(
            parked_entry_count(&reuse, &spec_reuse, &dspark_reuse),
            GLOBAL_CAP
        );
        assert!(
            reuse
                .values()
                .chain(spec_reuse.values())
                .chain(dspark_reuse.values())
                .all(|pool| pool.len() <= PER_NAMESPACE_CAP)
        );
        assert_eq!(metrics.continuation_evictions, 2);
        assert_eq!(metrics.spec_evictions, 1);
    }

    #[test]
    fn cache_alloc_oom_reclaim_retries_exactly_once() {
        let attempts = std::cell::Cell::new(0usize);
        let reclaims = std::cell::Cell::new(0usize);
        let result: Result<(), &'static str> = alloc_with_single_reclaim_retry(
            || {
                attempts.set(attempts.get() + 1);
                Err("DriverError(CUDA_ERROR_OUT_OF_MEMORY, out of memory)")
            },
            |err| {
                assert!(is_cuda_oom(err));
                reclaims.set(reclaims.get() + 1);
                true // models one oldest parked entry released
            },
        );

        assert!(result.is_err());
        assert_eq!(attempts.get(), 2, "one initial allocation plus one retry");
        assert_eq!(
            reclaims.get(),
            1,
            "reclaim runs only after the first failure"
        );

        let non_oom_attempts = std::cell::Cell::new(0usize);
        let result: Result<(), &'static str> = alloc_with_single_reclaim_retry(
            || {
                non_oom_attempts.set(non_oom_attempts.get() + 1);
                Err("CUDA_ERROR_INVALID_VALUE")
            },
            |err| is_cuda_oom(err),
        );
        assert!(result.is_err());
        assert_eq!(
            non_oom_attempts.get(),
            1,
            "a failure without reclaimed state is not retried",
        );
    }

    /// RED ARM for the 2026-09-10 context-fallback defect. Every one of these cases returned
    /// 8192 before the fix, which is what made an unset `MEMRA_CTX` publish and serve 8k against
    /// a checkpoint declaring a million positions. If the literal fallback is ever reintroduced,
    /// the first four assertions fail.
    #[test]
    fn an_unset_ctx_resolves_to_the_models_own_declared_context_never_a_constant() {
        assert_eq!(
            resolve_ctx(None, 1_048_576),
            Ok(1_048_576),
            "DSV4F declares max_position_embeddings 1048576; an unset MEMRA_CTX must serve it",
        );
        assert_eq!(resolve_ctx(None, 262_144), Ok(262_144));
        assert_eq!(resolve_ctx(None, 32_768), Ok(32_768));
        assert_eq!(
            resolve_ctx(None, 4_096),
            Ok(4_096),
            "a model SMALLER than the old constant must not be widened to it either",
        );

        // An explicit setting is authoritative in both directions: the fleet launchers pin it,
        // and a pinned window narrower than the checkpoint is a deployment decision.
        assert_eq!(resolve_ctx(Some("262144"), 1_048_576), Ok(262_144));
        assert_eq!(resolve_ctx(Some(" 8192 "), 1_048_576), Ok(8_192));

        // Fail closed where the value is real ambiguity, rather than substituting a number
        // that contradicts the checkpoint.
        for bad in ["", "abc", "-1", "1048576tokens", "0"] {
            let resolved = resolve_ctx(Some(bad), 1_048_576);
            assert!(
                resolved.is_err(),
                "MEMRA_CTX {bad:?} must refuse, not resolve to a guess (got {resolved:?})",
            );
        }
        assert!(
            resolve_ctx(None, 0).is_err(),
            "an undeclared model context with no MEMRA_CTX must refuse, not guess",
        );

        // And a declaration the engine cannot carry refuses rather than quietly narrowing to
        // whatever it can: the three refusals are told apart by their text.
        let beyond = resolve_ctx(None, ENGINE_MAX_CTX + 1).expect_err("beyond ceiling");
        assert!(beyond.contains("ceiling"), "{beyond}");
        assert_ne!(resolve_ctx(None, ENGINE_MAX_CTX + 1), Ok(ENGINE_MAX_CTX));
        assert_eq!(resolve_ctx(None, ENGINE_MAX_CTX), Ok(ENGINE_MAX_CTX));
    }

    /// The resolution must survive the request path, not only the resolver: an unbounded request
    /// against a 1M checkpoint with no `MEMRA_CTX` must be admitted at the checkpoint's window.
    /// With the old 8192 fallback this cap came out at `prompt + 8192`.
    ///
    /// `open_output_tokens: None` is the memory-admission door OFF, which is what this row is
    /// about: it pins the `MEMRA_CTX` envelope behaviour the door later replaces, so the two
    /// arms stay separately testable.
    #[test]
    fn an_unbounded_request_on_an_unset_ctx_is_capped_by_the_checkpoint_not_by_8192() {
        let server_ctx = resolve_ctx(None, 1_048_576).expect("declared context resolves");
        assert_eq!(
            request_ctx_cap(
                server_ctx,
                1_048_576,
                600_000,
                None,
                MAX_NEW_CTX_BOUNDED,
                None
            ),
            1_048_576,
            "a 600k prompt with no max_tokens must reach the checkpoint's window",
        );
        assert_eq!(
            request_ctx_cap(8_192, 1_048_576, 600_000, None, MAX_NEW_CTX_BOUNDED, None),
            608_192,
            "the pre-fix constant is what this row pins, so the delta is visible in the test",
        );
    }

    #[test]
    fn admission_request_context_uses_the_requests_own_bound() {
        assert_eq!(
            request_ctx_cap(262_144, 262_144, 128, Some(131_072), 64, None),
            131_072,
            "an explicit 128k request must not inherit the 262k server default",
        );
        assert_eq!(
            request_ctx_cap(8_192, 262_144, 128, Some(4_096), 64, None),
            4_096
        );
        assert_eq!(
            request_ctx_cap(8_192, 262_144, 200_000, None, 131_072, None),
            262_144,
            "finite prompt plus output must never allocate beyond trained context",
        );
        assert_eq!(
            request_ctx_cap(8_192, 262_144, 128, Some(524_288), 64, None),
            262_144,
            "an explicit max_ctx above trained context must remain model-capped",
        );
        assert_eq!(
            request_ctx_cap(8_192, 262_144, 260_000, None, MAX_NEW_CTX_BOUNDED, None),
            262_144,
            "omitted max_tokens uses the server default and remains model-capped",
        );
    }

