    #[test]
    fn prefix_fanout_rewrites_one_provisional_miss_exactly_once() {
        let mut px = PrefixCache {
            misses: 2,
            ..Default::default()
        };
        px.record_lcp(0);
        px.record_lcp(0);
        px.promote_miss_to_hit(0, 256);
        assert_eq!(px.misses, 1);
        assert_eq!(px.hits, 1);
        assert_eq!(px.hit_tokens, 256);
        assert_eq!(px.lcp_hist[PrefixCache::lcp_bucket(0)], 1);
        assert_eq!(px.lcp_hist[PrefixCache::lcp_bucket(256)], 1);
        assert_eq!(px.lcp_hist.iter().sum::<u64>(), 2);
    }

    /// A sized entry for the KV-flex byte-accounting cells: `entry()` with controllable
    /// residency bytes and distinct token keys (exact-token dedup would swallow twins).
    fn sized_entry(pool_key: &PoolKey, salt: u32, bytes: usize) -> PrefixEntry {
        let mut t = toks(PREFIX_CACHE_MIN_TOKENS);
        t[0] = u32::MAX - salt;
        let mut e = entry(pool_key, t);
        e.bytes = bytes;
        e
    }

    fn armed_flex(floor: usize) -> KvFlex {
        KvFlex {
            armed: true,
            floor,
            guard: 0,
            hold: std::time::Duration::from_secs(60),
            hold_until: None,
            sheds: 0,
            shed_ms_total: 0.0,
        }
    }

    /// The shed's eviction body: down to the target in capacity order, pins untouchable,
    /// terminates when nothing is evictable, evictions counted in the one accountant.
    #[test]
    fn kv_flex_evict_to_bytes_sheds_to_the_target_and_spares_pins() {
        let k = key("");
        let mut px = PrefixCache::default();
        for salt in 0..4 {
            px.insert_with_budget(&k, sized_entry(&k, salt, 10), "flex-test", 100);
        }
        assert_eq!(px.total_bytes, 40);
        let pin = px.pin_n(&k, 0, 1).expect("pinnable entry");
        let evictions_before = px.evictions;

        let (n, freed) = px.evict_to_bytes(20);
        assert_eq!((n, freed), (2, 20), "two 10-byte victims reach the target");
        assert_eq!(px.total_bytes, 20);
        assert_eq!(px.evictions, evictions_before + 2);

        // Target below the pinned residency: the loop stops at no-victim instead of
        // hanging or touching the lease.
        let (n, freed) = px.evict_to_bytes(0);
        assert_eq!((n, freed), (1, 10), "only the unpinned entry is evictable");
        assert_eq!(px.total_bytes, 10, "the pinned entry's bytes remain");
        assert!(px.unpin(&pin));
    }

    /// memra#523 item 1, review: a leased entry is never a pressure-relief victim, whatever the
    /// target; when only leased bytes remain the loop reports zero and `evictable_bytes()` is
    /// zero, the one shape the kv-flex "nothing evictable" line may describe.
    #[test]
    fn evict_to_bytes_never_takes_a_leased_entry_even_below_target() {
        const BUDGET: usize = 100;
        let k = key("");
        let mut px = PrefixCache::default();
        for ident in 0..3u32 {
            px.insert_with_budget(&k, entry_b(&k, ident, 10), "seed", BUDGET);
            assert!(reuse_ident(&mut px, ident));
        }
        px.insert_with_budget(&k, entry_b(&k, 3, 10), "seed", BUDGET);
        let i1 = px.entries[&k].iter().position(|e| e.toks[0] == 1).unwrap();
        let pin = px.pin(&k, i1).expect("a reused entry takes a lease");
        assert_eq!(px.evictable_bytes(), 30);

        assert_eq!(
            px.evict_to_bytes(0),
            (3, 30),
            "every unleased entry goes, the leased one stays"
        );
        assert_eq!(px_survivors(&px), vec![1]);
        assert_eq!(px.total_bytes, 10);
        assert_eq!(px.evictable_bytes(), 0);
        assert_eq!(
            px.evict_to_bytes(0),
            (0, 0),
            "nothing unleased: a no-op that reports zero"
        );
        assert!(px.unpin(&pin));
        assert_eq!(px.evictable_bytes(), 10);
        assert_prefix_cache_accounting(&px);
    }

    /// memra#523 item 1, review: the kv-flex shed reaches its floor through unleased bytes,
    /// reused or not (it counts as a shed, no warning path), and takes the "nothing
    /// evictable" path only when every byte above the floor is leased.
    #[test]
    fn kv_flex_shed_reaches_the_floor_through_reused_entries_and_warns_only_when_all_is_leased() {
        let k = key("");
        let mut px = PrefixCache::default();
        for ident in 0..3u32 {
            px.insert_with_budget(&k, entry_b(&k, ident, 10), "seed", 100);
            assert!(reuse_ident(&mut px, ident));
        }
        assert_eq!(px.total_bytes, 30);

        let mut flex = armed_flex(15);
        assert_eq!(
            flex.shed(&mut px, false, "test"),
            2,
            "unleased bytes above the floor shed, oldest first, reused or not"
        );
        assert_eq!(px_survivors(&px), vec![2]);
        assert_eq!(px.total_bytes, 10);
        assert_eq!(
            flex.sheds, 1,
            "a real shed is counted; the warning path never counts"
        );

        let i2 = px.entries[&k].iter().position(|e| e.toks[0] == 2).unwrap();
        let pin = px.pin(&k, i2).expect("the survivor takes a lease");
        let mut flex = armed_flex(5);
        assert_eq!(px.evictable_bytes(), 0);
        assert_eq!(
            flex.shed(&mut px, false, "test"),
            0,
            "everything above the floor is leased: the warning path"
        );
        assert_eq!(flex.sheds, 0);
        assert_eq!(px.total_bytes, 10);
        assert!(px.unpin(&pin));
        assert_prefix_cache_accounting(&px);
    }

    /// The grant policy, pure: free minus guard while armed, zero under hold, zero
    /// disarmed, saturating: a grant can never underflow into a giant budget.
    #[test]
    fn kv_flex_grant_policy_is_guarded_held_and_disarmed_to_zero() {
        let now = std::time::Instant::now();
        let mut f = armed_flex(100);
        f.guard = 1000;
        assert_eq!(
            f.grant_for(5000, now),
            4000,
            "free above the guard is grantable"
        );
        assert_eq!(
            f.grant_for(999, now),
            0,
            "the guard saturates, never underflows"
        );
        f.hold_until = Some(now + std::time::Duration::from_secs(1));
        assert_eq!(
            f.grant_for(5000, now),
            0,
            "an armed hold parks the grant at 0"
        );
        f.hold_until = Some(now - std::time::Duration::from_secs(1));
        assert_eq!(
            f.grant_for(5000, now),
            4000,
            "an expired hold re-opens the grant"
        );
        f.armed = false;
        assert_eq!(f.grant_for(5000, now), 0, "disarmed is always 0");
    }

    /// The shed transition end to end, and every assertion that reads the published
    /// grant static, kept in ONE test so parallel test threads cannot interleave on it.
    #[test]
    fn kv_flex_shed_returns_borrowed_bytes_to_the_floor_and_counts_the_transition() {
        let k = key("");
        let mut px = PrefixCache::default();
        for salt in 0..3 {
            px.insert_with_budget(&k, sized_entry(&k, salt, 10), "flex-test", 100);
        }
        let mut f = armed_flex(10);

        // OFF is identity: with the grant at 0 the effective budget IS the floor budget.
        KV_FLEX_GRANT.store(0, std::sync::atomic::Ordering::Relaxed);
        assert_eq!(kv_flex_effective_budget(), prefix_cache_budget_bytes());
        KV_FLEX_GRANT.store(7, std::sync::atomic::Ordering::Relaxed);
        assert_eq!(
            kv_flex_effective_budget(),
            prefix_cache_budget_bytes() + 7,
            "the effective budget is floor + published grant"
        );

        // Capture-arrival shed: grant zeroed, residency back at the floor, transition
        // counted with its wall time, hold armed against re-borrowing mid-burst.
        assert_eq!(f.borrowed_bytes(&px), 20);
        let n = f.shed(&mut px, true, "test capture");
        assert_eq!(n, 2, "both borrowed entries evaporate");
        assert_eq!(px.total_bytes, 10, "residency is back at the floor");
        assert_eq!(f.borrowed_bytes(&px), 0);
        assert_eq!(
            KV_FLEX_GRANT.load(std::sync::atomic::Ordering::Relaxed),
            0,
            "the shed unpublishes the grant"
        );
        assert_eq!(f.sheds, 1);
        assert!(f.shed_ms_total >= 0.0);
        assert!(
            f.hold_until.is_some_and(|t| t > std::time::Instant::now()),
            "a capture arrival arms the hold"
        );
        assert_eq!(
            f.grant_for(usize::MAX, std::time::Instant::now()),
            0,
            "no grant re-opens during the hold"
        );

        // Nothing borrowed: the shed is a no-op that must NOT inflate the transition
        // counter (an embeddings array admits one request per input; only the first
        // arrival of a burst finds borrowed bytes).
        assert_eq!(f.shed(&mut px, true, "test capture"), 0);
        assert_eq!(f.sheds, 1, "a no-op arrival is not a shed transition");

        // Disarmed: shed refuses to touch the cache at all.
        let mut off = armed_flex(0);
        off.armed = false;
        assert_eq!(off.shed(&mut px, true, "test off"), 0);
        assert_eq!(px.total_bytes, 10);
        assert_eq!(off.borrowed_bytes(&px), 0, "disarmed borrow gauge reads 0");
    }

    /// WIRING (the wiring-assertions law: anchor on invocations in comment-stripped
    /// source, never on prose). The capture-arrival shed must run inside the admission
    /// pass, guarded on the request's capture marker, BEFORE the VRAM headroom math.
    #[test]
    fn kv_flex_shed_on_capture_arrival_is_wired_before_admission_math() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let shed_at = code
            .find("kv_flex.shed(&mut px, true, \"capture arrival\")")
            .expect("the capture-arrival shed invocation exists");
        let guard_at = code[..shed_at]
            .rfind("if req.capture.is_some()")
            .expect("the capture guard exists upstream of the shed");
        assert!(
            shed_at - guard_at < 200,
            "the arrival shed must be guarded on the request's capture marker"
        );
        let required_at = code
            .find("let required = admission_required(cost, reserve);")
            .expect("the admission requirement site exists");
        assert!(
            shed_at < required_at,
            "the borrowed slice must yield BEFORE the capture request's admission math"
        );
    }

    /// WIRING: at admission insufficiency, the borrowed slice sheds FIRST, before the
    /// nuclear reclaim ladder evaporates the floor residency the operator budgeted.
    #[test]
    fn kv_flex_borrowed_first_shed_precedes_the_nuclear_reclaim_ladder() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let shed_at = code
            .find("kv_flex.shed(&mut px, false, \"admission headroom\")")
            .expect("the headroom shed invocation exists");
        // memra#365 moved the spelling, not the position: the flush is now a door-aware
        // binding whose OFF arm is `px.evict_all()` verbatim. The invariant this test guards
        // (borrowed-first shed immediately upstream of the nuclear ladder) is unchanged.
        let evict_at = code[shed_at..]
            .find("let (evicted_prefix, demoted_prefix, demoted_prefix_bytes) =")
            .expect("the reclaim flush exists downstream of the shed");
        assert!(
            code[shed_at + evict_at..].contains("(px.evict_all(), 0, 0)"),
            "the door-off arm of the flush must remain the verbatim evict_all ladder"
        );
        assert!(
            evict_at < 2500,
            "the borrowed-first shed must sit immediately upstream of the evict_all ladder"
        );
        let gate_at = code[..shed_at]
            .rfind("!headroom.sufficient(required)")
            .expect("the insufficiency gate exists upstream of the shed");
        assert!(
            shed_at - gate_at < 400,
            "the headroom shed fires only on admission insufficiency"
        );
    }

    /// WIRING, single-owner law (tiering spec Arc G: \"budget accounting must have ONE
    /// allocator owner or the design is wrong\"): the grant static is written only by
    /// KvFlex methods, both production insert wrappers consult the ONE effective-budget
    /// function, and the /metrics gauge derives from the one byte accountant.
    #[test]
    fn kv_flex_single_owner_wiring() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let prod = &code[..code.find("\nmod tests").expect("tests module exists")];

        // Every production write of the grant lives inside impl KvFlex.
        let impl_start = prod.find("impl KvFlex {").expect("impl KvFlex exists");
        let impl_end = impl_start
            + prod[impl_start..]
                .find("\nfn prefix_latent_planes_on")
                .expect("impl KvFlex ends before prefix_latent_planes_on");
        let stores: Vec<usize> = prod
            .match_indices("KV_FLEX_GRANT.store(")
            .map(|(i, _)| i)
            .collect();
        assert_eq!(
            stores.len(),
            2,
            "exactly two production grant writers: refresh_grant and shed"
        );
        for i in stores {
            assert!(
                i > impl_start && i < impl_end,
                "a grant write escaped impl KvFlex: a second budget owner"
            );
        }

        // Both production insert wrappers consult the one effective-budget function and
        // no longer read the bare floor themselves.
        for wrapper in ["fn insert_demoting(", "fn insert_pinned_demoting("] {
            let start = prod.find(wrapper).expect("wrapper exists");
            let body = &prod[start..];
            let flexed_at = body
                .find("kv_flex_effective_budget()")
                .expect("the flexed budget is consulted");
            assert!(
                flexed_at < 900,
                "{wrapper} must consult kv_flex_effective_budget"
            );
            assert!(
                body.find("prefix_cache_budget_bytes()")
                    .is_none_or(|i| i > 900),
                "{wrapper} must not read the bare floor beside the flexed budget"
            );
        }

        // The /metrics borrow gauge derives from the one byte accountant, never a
        // second counter.
        assert!(
            prod.contains("m.kv_flex_borrowed_bytes = kv_flex.borrowed_bytes(&px) as u64;"),
            "the metrics publish must derive borrowed bytes via KvFlex::borrowed_bytes"
        );
        assert!(
            prod.contains("m.kv_flex_sheds = kv_flex.sheds;")
                && prod.contains("m.kv_flex_shed_ms = kv_flex.shed_ms_total;"),
            "shed transition counters must publish to /metrics"
        );
    }

    /// PREDICTIVE-ADMISSION SHADOW wiring (lane/d2-engine-gaps-20260831, darklanes Arc
    /// D2 gaps G2/G3/G5): anchored on INVOCATIONS in comment-stripped production text,
    /// per the wiring-assertions law: a rationale comment must never satisfy this.
    /// memra#144: a non-hyper cost model charges the prime workspace, chunk-bounded under a
    /// chunked prime and prompt-scaled under a monolithic one, and the pre-lane model (no
    /// shape) still charges nothing (the red arm the receipts were banked against).
    #[test]
    fn non_hyper_prime_workspace_is_charged_and_chunk_bounded() {
        let shape = memra_engine::hybrid_forward::PrimeWorkspaceShape {
            call_row_bytes: 42 * 2048 + 14 * 2048,
            prompt_row_bytes: 4 * 2048,
            n_layers: 41,
        };
        let cost =
            |prime: Option<memra_engine::hybrid_forward::PrimeWorkspaceShape>| AdmissionCostModel {
                plain_bytes_per_token: 10_208,
                spec_bytes_per_token: 10_208,
                plain_ring_bytes_per_token: 0,
                spec_ring_bytes_per_token: 0,
                ring_rows: 0,
                activation_bytes: 129 << 20,
                prefill: None,
                prime,
                transient_floor: None,
                pp_activation_bytes: [0; 4],
                last_logged: None,
            };
        let with = cost(Some(shape));
        let without = cost(None);
        assert_eq!(
            without.prefill_workspace_bytes(164_515),
            0,
            "the pre-lane model charges nothing"
        );
        let charged = with.prefill_workspace_bytes(164_515);
        assert!(
            charged >= 164_515 * shape.prompt_row_bytes,
            "hiddens are always charged: {charged}"
        );
        // The charge follows the deployment's chunking (MEMRA_PRIME_CHUNK); the pure
        // arithmetic is pinned in memra-engine. Here: the estimate carries the term.
        assert_eq!(
            with.estimate(196_579, 164_515, true) - without.estimate(196_579, 164_515, true),
            charged
        );
    }

    /// memra#153: the enforce branch sits at the D2 seam (after the KV verdict receipt,
    /// before the VRAM-aware gate and every prefill), releases the admission reservation,
    /// answers the shed 429 with the stable sentence, and never fires for an exempt tenant.
    #[test]
    fn admit_predict_enforce_wiring() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let prod = &code[..code.find("\nmod tests").expect("tests module exists")];
        let flat: String = prod.chars().filter(|c| !c.is_whitespace()).collect();
        let verdict_line = flat
            .find("kv_hat_bytes:Some(request_kv_hat),")
            .expect("the KV verdict receipt exists");
        let enforce = flat
            .find("ifadmit_predict_cfg.enforce&&verdict==crate::admit_predict::Verdict::RejectKv&&!admit_predict_cfg.is_exempt(&tenant_row)")
            .expect("the enforce branch exists with the exempt guard");
        let gate = prod
            .find("let reserve = admission_reserve(")
            .map(|_| {
                flat.find("letreserve=admission_reserve(")
                    .expect("flat gate")
            })
            .expect("the VRAM-aware gate exists");
        assert!(
            verdict_line < enforce && enforce < gate,
            "enforce sits between the receipt and the real gate"
        );
        let branch = &flat[enforce..enforce + 400];
        assert!(
            branch.contains("release_admission_reservation(req.lane);"),
            "the reservation is released"
        );
        assert!(branch.contains("EngineError::rate_limit_after(crate::admit_predict::ENFORCED_KV_REJECT_MESSAGE,retry_after_s.unwrap_or(5),)"), "the shed 429 carries the stable sentence and the predicted retry");
        assert!(
            branch.contains("continue;"),
            "the request never reaches prefill"
        );
        // The live arm is read only under the door (shadow mode stays a pure log).
        assert!(flat.contains("letlive_free_bytes=ifadmit_predict_cfg.enforce{effective_free_bytes(&engine).map(|(free,_)|freeasu64)}else{None};"));
    }

    const SUBPROC_TEST_NAME: &str = "worker::tests::admit_predict_enforce_boot_subprocess_runner";
    const SUBPROC_ENV_VAR: &str = "MEMRA_ADMIT_PREDICT_BOOT_SUBPROC_CASE";

    fn cuda_available() -> bool {
        let prev_hook = std::panic::take_hook();
        std::panic::set_hook(Box::new(|_| {}));
        let res = std::panic::catch_unwind(|| Engine::new(0)).is_ok_and(|r| r.is_ok());
        std::panic::set_hook(prev_hook);
        res
    }

    /// Child process runner for admission-prediction boot qualification tests.
    #[test]
    fn admit_predict_enforce_boot_subprocess_runner() {
        let Some(case) = std::env::var(SUBPROC_ENV_VAR).ok() else {
            return; // Normal cargo test run, return cleanly
        };

        match case.as_str() {
            "single_gpu" => {
                if cuda_available() {
                    let health = crate::health::SharedHealth::default();
                    match spawn(vec![], health) {
                        Ok((cmd_tx, _names, _caps, _tokenizers, _metrics, worker_thread)) => {
                            drop(cmd_tx);
                            let _ = worker_thread.join();
                            std::process::exit(0);
                        }
                        Err(err) => {
                            eprintln!("single_gpu spawn failed unexpectedly: {err}");
                            std::process::exit(1);
                        }
                    }
                } else {
                    let loaded = HashMap::new();
                    if let Err(err) = validate_admit_predict_enforce_deployment(true, &loaded) {
                        eprintln!("single_gpu deployment validation failed: {err}");
                        std::process::exit(1);
                    }
                    std::process::exit(0);
                }
            }
            "pp" => {
                let health = crate::health::SharedHealth::default();
                match spawn(vec![], health) {
                    Ok((cmd_tx, _, _, _, _, worker_thread)) => {
                        drop(cmd_tx);
                        let _ = worker_thread.join();
                        eprintln!("pp unexpectedly succeeded boot");
                        std::process::exit(0);
                    }
                    Err(err) => {
                        eprintln!("{err}");
                        std::process::exit(1);
                    }
                }
            }
            "explicit_tp_ep" => {
                let health = crate::health::SharedHealth::default();
                match spawn(vec![], health) {
                    Ok((cmd_tx, _, _, _, _, worker_thread)) => {
                        drop(cmd_tx);
                        let _ = worker_thread.join();
                        eprintln!("explicit_tp_ep unexpectedly succeeded boot");
                        std::process::exit(0);
                    }
                    Err(err) => {
                        eprintln!("{err}");
                        std::process::exit(1);
                    }
                }
            }
            "automatic_ep" => {
                let health = crate::health::SharedHealth::default();
                match spawn(vec![], health) {
                    Ok((cmd_tx, _, _, _, _, worker_thread)) => {
                        drop(cmd_tx);
                        let _ = worker_thread.join();
                        eprintln!("automatic_ep unexpectedly succeeded boot");
                        std::process::exit(0);
                    }
                    Err(err) => {
                        eprintln!("{err}");
                        std::process::exit(1);
                    }
                }
            }
            "env_unset_after_load" => {
                // Strip all ambient multi-device env vars to prove structural detection
                unsafe {
                    std::env::remove_var("MEMRA_PP_STAGES");
                    std::env::remove_var("MEMRA_PP_DEVICES");
                    std::env::remove_var("MEMRA_STEP_TP");
                    std::env::remove_var("MEMRA_STEP_EP");
                    std::env::remove_var("MEMRA_PARALLEL");
                    std::env::remove_var("MEMRA_PARALLEL_DEVICES");
                    std::env::remove_var("MEMRA_GLM5_TP");
                }

                if cuda_available() {
                    // Micro fixture loaded on GPU 0
                    let p = std::env::temp_dir()
                        .join(format!("memra-test-load-{}.gguf", std::process::id()));
                    let _ = memra_gguf::micro_gguf::write_glm_dsa_micro(&p, 0x6_10AD_0802).unwrap();
                    let g = memra_gguf::GgufFile::open(&p).unwrap();
                    let e = Engine::new(0).expect("CUDA device 0");
                    let mut model = HybridModel::load(&e, &g).expect("micro fixture loads");
                    let tok = Arc::new(Tokenizer::from_gguf(&g).expect("tokenizer"));
                    std::fs::remove_file(&p).ok();

                    // Structural multi-device configuration (as established by automatic EP or TP)
                    model.test_extra_devices = vec![0, 1];
                    assert!(model.is_multi_device());

                    let mut loaded = HashMap::new();
                    loaded.insert(
                        "structural_ep_model".into(),
                        LoadedModel::new_for_test(model, tok),
                    );

                    // In shadow mode (enforce=false), structural multi-device is allowed
                    if let Err(err) = validate_admit_predict_enforce_deployment(false, &loaded) {
                        eprintln!("shadow mode unexpectedly refused: {err}");
                        std::process::exit(0);
                    }

                    // Under enforcement (enforce=true), structural multi-device MUST fail closed
                    match validate_admit_predict_enforce_deployment(true, &loaded) {
                        Ok(()) => {
                            eprintln!(
                                "env_unset_after_load unexpectedly bypassed structural guard"
                            );
                            std::process::exit(0);
                        }
                        Err(err) => {
                            eprintln!("{err}");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("{ADMIT_PREDICT_MULTI_DEVICE_FATAL_MSG}");
                    std::process::exit(1);
                }
            }
            other => {
                eprintln!("unknown subproc case: {other}");
                std::process::exit(2);
            }
        }
    }

    #[test]
    fn admit_predict_enforce_boot_single_gpu() {
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .arg(SUBPROC_TEST_NAME)
            .arg("--exact")
            .arg("--nocapture")
            .env(SUBPROC_ENV_VAR, "single_gpu")
            .env("MEMRA_ADMIT_PREDICT_ENFORCE", "1")
            .output()
            .unwrap();
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            output.status.success(),
            "single-GPU boot must succeed under MEMRA_ADMIT_PREDICT_ENFORCE=1\nstdout:\n{stdout}\nstderr:\n{stderr}"
        );
        assert!(
            !stderr.contains(ADMIT_PREDICT_MULTI_DEVICE_FATAL_MSG),
            "single GPU must not log multi-device fatal message"
        );
    }

