    #[test]
    fn admit_predict_is_multi_device_deployment_unit_checks() {
        let empty: HashMap<String, LoadedModel> = HashMap::new();
        assert!(!is_multi_device_deployment(&empty));

        assert_eq!(
            evaluate_predictive_admission_verdict(100, 100, Some(300)),
            crate::admit_predict::Verdict::Admit
        );
        assert_eq!(
            evaluate_predictive_admission_verdict(100, 250, Some(300)),
            crate::admit_predict::Verdict::RejectKv
        );
        assert_eq!(
            evaluate_predictive_admission_verdict(100, 250, None),
            crate::admit_predict::Verdict::Admit
        );
    }

    /// memra#187: multi-session concurrency accounting test.
    /// Proves that concurrent active sessions do not falsely trigger RejectKv as live_free drops,
    /// because the static capacity check is decoupled from the physical live headroom check.
    /// Directly drives the production evaluate_decoupled_admission predicate and headroom outcome.
    #[test]
    fn admit_predict_concurrency_decoupled_accounting() {
        let static_budget = 30_000_000_000u64; // 30 GB static budget
        let reserve = 2_000_000_000usize; // 2 GB transient reserve
        let initial_live_free = 32_000_000_000u64; // 32 GB physical free on idle card

        let mut book = crate::admit_predict::AdmissionBook::default();
        let mut live_free = initial_live_free;

        // Session charge parameters: 8 GB predicted demand per session
        let prompt_tokens = 4_000u64;
        let pred_tokens = 4_000u64;
        let bpt = 1_000_000u64;
        let ring_bpt = 0u64;
        let ring_rows = 0u64;
        let fixed = 0u64;

        let req_hat = crate::admit_predict::kv_hat_ring(
            prompt_tokens,
            pred_tokens,
            bpt,
            ring_bpt,
            ring_rows,
            fixed,
        );
        // (4000 + 4000 + 8) * 1_000_000 = 8_008_000_000 bytes (~8 GB)
        assert_eq!(req_hat, 8_008_000_000);
        let session_cost = req_hat as usize;

        // --- Session 1 arrives ---
        let booked_1 = book.shadow_booked_total();
        assert_eq!(booked_1, 0);
        let (verdict_1, outcome_1) = evaluate_decoupled_admission(
            req_hat,
            booked_1,
            Some(static_budget),
            true,  // enforce
            false, // exempt
            session_cost,
            reserve,
            live_free,
        );
        assert_eq!(verdict_1, crate::admit_predict::Verdict::Admit);
        assert_eq!(outcome_1, EvaluatedAdmissionOutcome::Admitted);

        // Session 1 is admitted and allocates memory
        book.admit("model", req_hat, req_hat);
        live_free -= req_hat;
        assert_eq!(live_free, 23_992_000_000);

        // --- Session 2 arrives ---
        let booked_2 = book.shadow_booked_total();
        assert_eq!(booked_2, req_hat);
        let (verdict_2, outcome_2) = evaluate_decoupled_admission(
            req_hat,
            booked_2,
            Some(static_budget),
            true,  // enforce
            false, // exempt
            session_cost,
            reserve,
            live_free,
        );
        assert_eq!(verdict_2, crate::admit_predict::Verdict::Admit);
        assert_eq!(outcome_2, EvaluatedAdmissionOutcome::Admitted);

        // Session 2 is admitted and allocates memory
        book.admit("model", req_hat, req_hat);
        live_free -= req_hat;
        assert_eq!(live_free, 15_984_000_000);

        // --- Session 3 arrives ---
        let booked_3 = book.shadow_booked_total();
        assert_eq!(booked_3, req_hat * 2); // 16.016 GB booked

        // Under the old buggy coupled predicate:
        // arm = min(budget, live_free - reserve) = min(30 GB, ~13.984 GB) = 13.984 GB
        // and it checked req_hat + booked_3 (24.024 GB) > 13.984 GB -> FALSE REJECT!
        let old_arm = static_budget.min(live_free.saturating_sub(reserve as u64));
        assert!(
            req_hat + booked_3 > old_arm,
            "proves that the old coupled arm falsely rejects Session 3"
        );

        // Under the production evaluate_decoupled_admission:
        let (verdict_3, outcome_3) = evaluate_decoupled_admission(
            req_hat,
            booked_3,
            Some(static_budget),
            true,  // enforce
            false, // exempt
            session_cost,
            reserve,
            live_free,
        );
        assert_eq!(verdict_3, crate::admit_predict::Verdict::Admit);
        assert_eq!(outcome_3, EvaluatedAdmissionOutcome::Admitted);

        // Session 3 is admitted and allocates memory
        book.admit("model", req_hat, req_hat);
        live_free -= req_hat;
        assert_eq!(
            live_free, 7_976_000_000,
            "live_free drops by candidate demand after admit"
        );

        // --- Session 4 arrives (exceeds static capacity) ---
        let booked_4 = book.shadow_booked_total();
        assert_eq!(booked_4, req_hat * 3); // 24.024 GB booked
        let (verdict_4, outcome_4) = evaluate_decoupled_admission(
            req_hat,
            booked_4,
            Some(static_budget),
            true,  // enforce
            false, // exempt
            session_cost,
            reserve,
            live_free,
        );
        assert_eq!(verdict_4, crate::admit_predict::Verdict::RejectKv);
        assert_eq!(
            outcome_4,
            EvaluatedAdmissionOutcome::RejectedPredictiveKv,
            "Session 4 correctly rejected for exceeding static budget"
        );

        // --- Case 5: Exempt tenant exceeding static budget is bypassed to live headroom ---
        let (verdict_exempt, outcome_exempt) = evaluate_decoupled_admission(
            req_hat,
            booked_4,
            Some(static_budget),
            true, // enforce
            true, // is_exempt
            session_cost,
            reserve,
            30_000_000_000, // plenty of physical headroom
        );
        assert_eq!(verdict_exempt, crate::admit_predict::Verdict::RejectKv);
        assert_eq!(
            outcome_exempt,
            EvaluatedAdmissionOutcome::ExemptBypassAdmitted
        );

        // --- Case 6: Passes static check but fails physical live headroom ---
        let (verdict_headroom, outcome_headroom) = evaluate_decoupled_admission(
            req_hat,
            0, // no bookings, passes static check
            Some(static_budget),
            true,
            false,
            session_cost,
            reserve,
            5_000_000_000, // 5 GB < 8.008 GB + 2 GB reserve -> insufficient headroom
        );
        assert_eq!(verdict_headroom, crate::admit_predict::Verdict::Admit);
        assert_eq!(
            outcome_headroom,
            EvaluatedAdmissionOutcome::InsufficientPhysicalHeadroom
        );
    }

    /// memra#145: the step-OOM teardown reclaims the parked pools and the prefix cache BEFORE
    /// it fences and trims the pool, and the streak resets on a quiet tick. Anchored on
    /// invocations in comment-stripped production text.
    #[test]
    fn step_oom_teardown_reclaims_before_trim() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let prod = &code[..code.find("\nmod tests").expect("tests module exists")];
        let flat: String = prod.chars().filter(|c| !c.is_whitespace()).collect();
        let block = flat.find("ifoom_teardowns>0{").expect("teardown block");
        let end = flat[block..]
            .find("}else{oom_evict_streak=0;}")
            .expect("streak reset on a quiet tick")
            + block;
        let body = &flat[block..end];
        for call in [
            "reuse.clear();",
            "spec_reuse.clear();",
            "dspark_reuse.clear();",
            "px.evict_to_bytes(cache_before/2)",
            "px.evict_all()",
        ] {
            assert!(body.contains(call), "teardown reclaims via {call}");
        }
        let reclaim = body.find("reuse.clear();").unwrap();
        let fence = body
            .find("oom_teardown_fence(&engine,&loaded);")
            .expect("fence");
        let trim = body.find("trim_model_device_pools(").expect("trim");
        assert!(
            reclaim < fence && fence < trim,
            "reclaim, then fence, then trim"
        );
    }

    /// memra#524 (lane/spill-b-20260919 day 24): readiness waits for the one warmup the
    /// server itself runs. In `run`, the boot calibration probe (one spec-shaped generation
    /// through the real serving path: chunked prime, draft capture, sampled verify, pool
    /// high-water read) precedes the `ready_tx` send, and `/readyz` cannot flip before that
    /// send because `health.mark_ready()` follows it; until then `WorkerHealth` is in
    /// PHASE_LOADING (`health::tests::loading_is_not_live_and_not_ready`). Anchored on the
    /// comment-stripped production text so a reorder is a red test, not a log archaeology.
    #[test]
    fn readiness_follows_the_boot_calibration_probe() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let prod = &code[..code.find("\nmod tests").expect("tests module exists")];
        let run_at = prod.find("pub fn run(").expect("worker::run exists");
        let body = &prod[run_at..];
        let calibrate = body
            .find("run_boot_calibration(")
            .expect("run calls the boot calibration probe");
        let ready = body.find("ready_tx.send(Ok(").expect("run sends readiness");
        let mark = body
            .find("health.mark_ready();")
            .expect("run marks health ready");
        assert!(
            calibrate < ready && ready < mark,
            "boot calibration ({calibrate}) must precede the readiness send ({ready}), which must \
             precede health.mark_ready ({mark}): /readyz flips only after the warmup the server runs"
        );
        // The probe itself is the warmup: it runs a real generation, never a synthetic no-op.
        let probe_at = prod.find("fn run_boot_calibration(").expect("probe fn");
        let probe = &prod[probe_at..];
        assert!(
            probe.contains("generate_spec_session_sampled(")
                && probe.contains("dspark_spec_session_burst("),
            "the calibration probe generates through the real serving routes"
        );
        // Day 25: PHASE_WARMING is entered inside the probe, after every skip return (so a
        // probe-skipped boot never reports warming) and before the generation; `mark_ready`
        // in `run` ends it. The order on the armed path is loading -> warming -> idle.
        let probe_body = &probe[..probe.find("\n}\n").expect("probe fn ends")];
        let warming = probe_body
            .find("health.mark_warming();")
            .expect("the probe marks the warming phase");
        let last_skip = probe_body
            .rfind("return;")
            .expect("the probe has skip returns");
        let generate = probe_body
            .find("dspark_spec_session_burst(")
            .expect("probe generates");
        assert!(
            last_skip < warming && warming < generate,
            "mark_warming ({warming}) must follow the last skip return ({last_skip}) and precede \
             the probe generation ({generate})"
        );
        assert_eq!(
            probe_body.matches("health.mark_warming();").count(),
            1,
            "one warming site, inside the per-model probe loop"
        );
    }

    #[test]
    fn admit_predict_shadow_wiring() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let prod = &code[..code.find("\nmod tests").expect("tests module exists")];

        // G2: exactly one book-admit and one book-retire, so the book has one owner
        // per direction and stays exact by construction.
        assert_eq!(
            prod.matches("admission_book.admit(&s.model, s.booked_kv_bytes, s.shadow_kv_hat);")
                .count(),
            1,
            "one production book-admit"
        );
        assert_eq!(
            prod.matches("admission_book.retire(&s.model, s.booked_kv_bytes, s.shadow_kv_hat);")
                .count(),
            1,
            "one production book-retire"
        );
        // The admit charge sits at the active.push seam...
        let admit_at = prod
            .find("admission_book.admit(")
            .expect("book admit exists");
        let push_at = prod.find("active.push(s);").expect("active.push exists");
        assert!(
            admit_at < push_at && push_at - admit_at < 200,
            "book-admit must immediately precede active.push"
        );
        // ...and the retire release at the single active.remove seam.
        let remove_at = prod.find("active.remove(i)").expect("retire remove exists");
        let retire_at = prod
            .find("admission_book.retire(")
            .expect("book retire exists");
        assert!(
            retire_at > remove_at && retire_at - remove_at < 800,
            "book-retire must sit at the active.remove seam"
        );

        // G3: the completion history records exactly once, at retirement, and only for
        // terminal completions (parks re-admit; aborts are load, not completions).
        assert_eq!(prod.matches("completion_history.record(").count(), 1);
        assert!(
            prod.contains("if !s.oom_teardown && !s.aborted && !s.errored {"),
            "history excludes parks, aborts and errored sessions"
        );

        // G2 metrics: the /metrics gauges derive from the one book, never a twin counter.
        assert!(prod.contains("m.admission_inflight = admission_book.inflight_snapshot();"));
        assert!(prod.contains("m.admission_booked_bytes = admission_book.booked_snapshot();"));

        // G5: exactly two verdict emission sites (the slot arm pre-tokenize, the KV arm
        // post-tokenize), each behind the armed flag + the per-request one-shot latch,
        // and each inside an eprintln!: the shadow LOGS, it never answers a request.
        let sites: Vec<usize> = prod
            .match_indices("shadow_verdict_line(")
            .map(|(i, _)| i)
            .collect();
        assert_eq!(sites.len(), 2, "slot arm + kv arm, nothing else");
        for i in sites {
            let before = &prod[i.saturating_sub(120)..i];
            assert!(
                before.contains("eprintln!"),
                "a verdict site must be a log line, never a response path"
            );
        }
        assert_eq!(
            prod.matches("admit_predict_cfg.armed").count(),
            4,
            "slot arm, kv arm, the admit-time shadow book charge, and the boot \
             budget resolution"
        );
        assert_eq!(
            prod.matches("req.admit_predict_logged = true;").count(),
            2,
            "both arms latch the one-shot receipt"
        );

        // LIVE BUDGET DEFAULT (lane/admit-predict-calibration-20260901): the boot
        // resolution is invoked exactly once, and its derivation reads the engine's
        // own quantities (effective free, the prefix-cache budget, the real gate's
        // reserve arithmetic), never a second hand-rolled formula.
        assert_eq!(
            prod.matches("admit_predict_cfg.resolve_budget(derived);")
                .count(),
            1,
            "one boot budget resolution"
        );
        let resolve_at = prod
            .find("admit_predict_cfg.resolve_budget(derived);")
            .expect("resolution exists");
        let derive_block = &prod[resolve_at.saturating_sub(1600)..resolve_at];
        for input in [
            "effective_free_bytes(&engine)",
            "prefix_cache_budget_bytes() as u64",
            "admission_reserve(",
            "admit_reserve_override()",
        ] {
            assert!(
                derive_block.contains(input),
                "the derivation must read `{input}`"
            );
        }

        // Dual book (FINDING 3 calibration): both verdict sites carry the
        // engine-charge book beside the predictive one.
        assert_eq!(
            prod.matches("booked_real_bytes: admission_book.booked_total(),")
                .count(),
            2,
            "both arms log booked_real from the engine-charge book"
        );
    }

    /// FIRST-TOKEN DEADLINE GATE wiring (lane/bench-debts-20260901, competitive-bench
    /// engine debt 3): anchored on INVOCATIONS in comment-stripped production text
    /// (wiring-assertions law).
    #[test]
    fn first_token_deadline_gate_wiring() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let prod = &code[..code.find("\nmod tests").expect("tests module exists")];

        // ONE gate site, judging through the pure predicate.
        let sites: Vec<usize> = prod
            .match_indices("crate::admit_predict::first_token_wait_infeasible(")
            .map(|(i, _)| i)
            .collect();
        assert_eq!(sites.len(), 1, "exactly one production gate site");
        let i = sites[0];
        // Behind the flag, interactive-only, capture-exempt, judging the REMAINING
        // wire deadline and the live prime backlog.
        let before = &prod[i.saturating_sub(1000)..i];
        assert!(
            before.contains("first_token_deadline_gate_on()"),
            "the gate must be flag-guarded"
        );
        assert!(
            before.contains("lane == crate::lanes::Lane::Interactive"),
            "interactive lane only"
        );
        assert!(
            before.contains("req.capture.is_none()"),
            "capture requests bypass"
        );
        assert!(
            before.contains("req.wire_deadline"),
            "the wire deadline is the judged contract"
        );
        assert!(
            before.contains("s.prefill_queue.len()"),
            "the backlog is the live prime queue, not a proxy"
        );
        // The refusal is the shed contract: Retry-After constructor, reservation
        // released, and the request never falls through to admission.
        let after = &prod[i..(i + 2200).min(prod.len())];
        assert!(
            after.contains("EngineError::rate_limit_after("),
            "refusal takes the Retry-After shed constructor"
        );
        assert!(
            after.contains("release_admission_reservation(req.lane);"),
            "the lane reservation is released on refusal"
        );
        assert!(
            after.contains("continue;"),
            "a refused request never reaches admission"
        );
        // The receipt line is grep-stable.
        assert!(
            after.contains("[first-token-gate] id="),
            "the refusal logs a joined receipt line"
        );
        // The deadline is stamped at every handler submission seam beside the receipt
        // identity: the two lib.rs handlers plus the shared surfaces body.
        for (file, want) in [
            (include_str!("lib.rs"), 2usize),
            (include_str!("surfaces.rs"), 1usize),
        ] {
            let stripped: String = file
                .lines()
                .map(|l| l.split("//").next().unwrap_or(""))
                .collect::<Vec<_>>()
                .join("\n");
            assert_eq!(
                stripped
                    .matches("wire_deadline = Some(deadline.at.into_std());")
                    .count(),
                want,
                "every handler submission stamps the wire deadline"
            );
        }
    }

    /// TOOTH for the H11 depth freeze (the measured 3.1x lever, canonflip-20260813):
    /// the seed decision must compare DEPTH against the deepest covering entry, never a
    /// boolean covering check. Under the pre-fix rule (`has_covering` -> skip), the shallow
    /// 100-token system-prompt entry froze the 4,860-token class forever.
    #[test]
    fn prefix_seed_deepens_past_a_shallow_covering_entry() {
        let mut px = PrefixCache::default();
        let shallow = toks(PREFIX_CACHE_MIN_TOKENS + 36); // the "100-token" class entry
        let deep_prompt = toks(4860);
        px.insert(&key("t"), entry(&key("t"), shallow.clone()), "test");

        // the covering boolean is TRUE — exactly the state that used to refuse the seed...
        assert!(px.has_covering(&key("t"), &deep_prompt));
        // ...and the depth reading unfreezes it: 4860 - 100 >> deepen floor.
        assert_eq!(
            px.deepest_covering(&key("t"), &deep_prompt),
            Some(shallow.len())
        );
        assert!(super::prefix_seed_deepens(
            px.deepest_covering(&key("t"), &deep_prompt),
            deep_prompt.len()
        ));

        // deepest_covering picks the DEEPEST cover, not the first.
        px.insert(&key("t"), entry(&key("t"), toks(2048)), "test");
        assert_eq!(px.deepest_covering(&key("t"), &deep_prompt), Some(2048));
        // a non-covering (diverging) entry never counts as cover.
        let mut diverged = toks(4096);
        diverged[3000] ^= 1;
        px.insert(&key("t"), entry(&key("t"), diverged), "test");
        assert_eq!(px.deepest_covering(&key("t"), &deep_prompt), Some(2048));

        // deepen floor: equal depth and sub-floor gains are churn, one entry-worth pays.
        assert!(super::prefix_seed_deepens(None, 4860));
        assert!(!super::prefix_seed_deepens(Some(4860), 4860));
        assert!(!super::prefix_seed_deepens(
            Some(4860 - super::prefix_seed_deepen_min() + 1),
            4860
        ));
        assert!(super::prefix_seed_deepens(
            Some(4860 - super::prefix_seed_deepen_min()),
            4860
        ));
    }

    #[test]
    fn hit_reseed_refuses_eager_only_models() {
        let arms = super::plain_hit_reseed_arms;
        // the qwen-class lever: a plain hit on a long prompt re-arms the seed.
        assert!(arms(true, true, false, 4860));
        // R16's hard prerequisite: an eager-only (gemma-class) hit NEVER re-arms — its
        // carried suffix rides tokenwise decode_step, so a "deepened" seed would publish
        // restore+decode_step chained provenance onto the H1 crossing.
        assert!(!arms(true, true, true, 4860));
        // the other refusals hold: no hit, spec path, sub-floor prompt.
        assert!(!arms(false, true, false, 4860));
        assert!(!arms(true, false, false, 4860));
        assert!(!arms(true, true, false, PREFIX_CACHE_MIN_TOKENS - 1));
    }

    /// lane/glm5-prefix-latent2 (2026-09-01): the carried-suffix prime carve-out is scoped
    /// to hyper trunks AND the flag — gemma-class eager-only models never carve out (their
    /// engine genuinely refuses pos>0 prime; the veto is load-bearing there).
    #[test]
    fn carried_suffix_prime_carveout_is_hyper_and_flag_scoped() {
        let p = super::carried_suffix_primes;
        // hyper trunk + flag = the carve-out (glm5 restored suffix rides the prime program)
        assert!(p(true, true));
        // flag off = today's tokenwise path, byte-identical (the rollback seam)
        assert!(!p(true, false));
        // gemma-class (not a hyper trunk) never carves out, flag or no flag
        assert!(!p(false, true));
        assert!(!p(false, false));
    }

    /// WIRING GATE (anchored on invocations in comment-stripped source, never prose —
    /// the wiring-assertions-match-prose law): the MEMRA_HYPER_SUFFIX_PRIME carve-out is
    /// LIVE at all four seams it claims (both prefill sites' veto terms + receipts, the
    /// H11 reseed narrowing, the hit-LCP deepening disjunction).
    #[test]
    fn suffix_prime_carveout_wiring_is_live_in_comment_stripped_source() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        // Assertions run over the PRE-TEST slice: this test's own string literals would
        // otherwise count themselves (comment-stripping does not strip strings).
        let live = &code[..code.find("mod tests").expect("the test module exists")];
        // 1. Both prefill sites compute the carve-out through the PURE predicate over the
        //    plan's hyper-trunk truth and the flag, and their veto terms consume it.
        assert_eq!(
            live.matches("carried_suffix_primes(").count(),
            5, // fn def + 2 prefill sites + reseed narrowing + hit-LCP deepening (update
            // this count AND this comment together when a new consumer lands)
            "the carve-out predicate must be consumed at exactly the claimed seams"
        );
        assert_eq!(
            live.matches("!(eager_mono && carried && !suffix_prime)")
                .count(),
            2,
            "both prefill sites (prefill_tick + step_session) must carry the lifted veto"
        );
        // Any THIRD variant of the veto expression (an unlifted reintroduction under
        // different formatting — PR #93 review finding 6a: the old newline-anchored
        // negative assertion passed on same-line braces) fails this exact count.
        assert_eq!(
            live.matches("(eager_mono && carried").count(),
            2,
            "exactly the two lifted veto forms may mention (eager_mono && carried"
        );
        // 2. The engagement receipt is an INVOCATION in both sites (the deploy gate greps
        //    the server log for it); the OFF arm announces DECLINED in both sites; the
        //    flag-ON tokenwise fallbacks (budget starvation, sub-floor suffix) announce
        //    TOKENWISE in both sites and set the provenance bit the capture sites refuse
        //    on (PR #93 review findings 3a + 5 — R16 as a checked invariant).
        assert_eq!(
            live.matches("\"[suffix-prime] ENGAGED:").count(),
            2,
            "both prefill sites must emit the ENGAGED receipt"
        );
        assert_eq!(
            live.matches("\"[suffix-prime] DECLINED (MEMRA_HYPER_SUFFIX_PRIME off):")
                .count(),
            2,
            "both prefill sites must announce the OFF-arm tokenwise suffix on hyper trunks"
        );
        assert_eq!(
            live.matches("\"[suffix-prime] TOKENWISE (flag on):")
                .count(),
            2,
            "both tokenwise branches must announce the flag-ON fallback on hyper trunks"
        );
        assert_eq!(
            live.matches("s.prompt_tok_decode_step = true;").count(),
            2,
            "both tokenwise branches must set the provenance bit"
        );
        assert_eq!(
            live.matches("if s.prompt_tok_decode_step {").count(),
            2,
            "both capture sites (maybe_prefix_seed + the lcp-split insert) must refuse on \
             the provenance bit"
        );
        // 3. The H11 reseed call site narrows the eager bit through the predicate.
        let reseed = live
            .find("if plain_hit_reseed_arms(")
            .expect("the H11 re-arm call site exists");
        assert!(
            live[reseed..reseed + 400].contains("&& !carried_suffix_primes("),
            "the reseed call site must pass the carve-out-narrowed eager bit"
        );
        // 4. The hit-LCP deepening carries the carve-out disjunction beside the eager
        //    veto. The invocation shape is the deepest-wins max over the LCP teacher and
        //    the stable boundary (lane/bench-debts-20260901); the carve-out anchor is
        //    unchanged.
        let deepen = live
            .find("lcp_taught.unwrap_or(0).max(stable.unwrap_or(0)),")
            .expect("the hit-LCP deepening site exists");
        assert!(
            live[deepen..deepen + 500].contains("|| carried_suffix_primes("),
            "the deepening site must admit prime-provenance hyper suffixes"
        );
    }

    #[test]
    fn hit_lcp_split_drops_the_sub_floor_fed_gap() {
        // grid = gdn_chunk_size() (32 shipped), fed-gap floor = PRIME_MIN_T (16), entry
        // floor = PREFIX_CACHE_MIN_TOKENS (64). `hit_len` is a prefill-done seed depth and
        // is NOT grid-aligned, so an aligned LCP can land 1..15 tokens past it — the gap
        // `prefill_tick`'s boundary veto refuses to prime, which would route those tokens
        // through tokenwise decode_step BEFORE the capture (the W1 two-programs door, with
        // the captured entry's tail carrying decode_step provenance).
        let bound = super::hit_lcp_snapshot_boundary;
        // the reachable door: la = 128, gap = 8 < 16 -> DROPPED (lose a seed, keep one
        // numeric program).
        assert_eq!(bound(130, 120, 200), None);
        // one grid unit deeper clears the floor and captures: la = 160, gap = 40.
        assert_eq!(bound(170, 120, 200), Some(160));
        // exactly the floor is legal.
        assert_eq!(bound(170, 144, 200), Some(160));
        // no deepening past the restored entry -> nothing to capture.
        assert_eq!(bound(120, 120, 200), None);
        assert_eq!(bound(90, 120, 200), None);
        // an aligned boundary under the entry floor never captures.
        assert_eq!(bound(50, 10, 200), None);
        // the prompt-side W1 step-down still applies first (within-behaviour preserved):
        // lcp at the prompt end steps 200 -> 192 -> 160, and the fed gap is measured from
        // the stepped boundary.
        assert_eq!(bound(200, 120, 200), Some(160));
    }

    #[test]
    fn seed_capture_boundary_lands_on_the_grid_or_refuses() {
        // memra#602 (research/spill-b-20260919/DAY17.md): the prompt-end seed obeys the same
        // grid law as the LCP and message-boundary captures. grid = gdn_chunk_size() (32
        // shipped), W1 remainder floor = PRIME_MIN_T (16), entry floor = PREFIX_CACHE_MIN_TOKENS
        // (64). Every case below is stated in grid units so the test holds under MEMRA_GDN_CHUNK.
        use super::{SeedCapture, seed_capture_boundary};
        let c = memra_engine::Engine::gdn_chunk_size();
        let floor = memra_engine::hybrid_forward::PRIME_MIN_T;
        let min = super::PREFIX_CACHE_MIN_TOKENS;
        assert!(
            c >= 2 * floor && min.is_multiple_of(c),
            "the shipped grain: c={c} floor={floor} min={min}"
        );
        // The day-17 lengths: 12,350 = 385*32 + 30 -> boundary 12,320 (remainder 30 >= floor);
        // 12,200 = 381*32 + 8 -> aligned 12,192 leaves 8 < floor, step down to 12,160.
        assert_eq!(
            seed_capture_boundary(12_350, 0),
            SeedCapture::AtBoundary(12_320)
        );
        assert_eq!(
            seed_capture_boundary(12_200, 0),
            SeedCapture::AtBoundary(12_160)
        );
        // exactly the prompt-end boundary: on the grid, the whole prompt publishes at
        // prefill-done (unchanged behaviour); 12,288 is the cold prime's own call start.
        assert_eq!(seed_capture_boundary(12_288, 0), SeedCapture::AtPromptEnd);
        assert_eq!(seed_capture_boundary(400 * c, 0), SeedCapture::AtPromptEnd);
        // just above a grid boundary: a remainder under the W1 floor steps down one grid unit.
        for tail in 1..floor {
            assert_eq!(
                seed_capture_boundary(400 * c + tail, 0),
                SeedCapture::AtBoundary(399 * c),
                "tail {tail}"
            );
        }
        // a remainder at or above the floor keeps the nearest grid line.
        for tail in floor..c {
            assert_eq!(
                seed_capture_boundary(400 * c + tail, 0),
                SeedCapture::AtBoundary(400 * c),
                "tail {tail}"
            );
        }
        // just below a grid boundary: the previous grid line (remainder c-1 >= floor).
        assert_eq!(
            seed_capture_boundary(400 * c - 1, 0),
            SeedCapture::AtBoundary(399 * c)
        );
        // an entry shorter than one grid step above the floor refuses, typed: prompts in
        // (min, min + floor) align to min - c, under the entry floor.
        for tail in 1..floor {
            assert_eq!(
                seed_capture_boundary(min + tail, 0),
                SeedCapture::Refused { aligned: min - c },
                "tail {tail}"
            );
        }
        // the floor itself is on the grid and publishes whole; floor + W1 remainder aligns to it.
        assert_eq!(seed_capture_boundary(min, 0), SeedCapture::AtPromptEnd);
        assert_eq!(
            seed_capture_boundary(min + floor, 0),
            SeedCapture::AtBoundary(min)
        );
        // ON A HIT the boundary must lie at least PRIME_MIN_T past the restored entry: an exact
        // re-send (entry == prompt) and a re-send extended by less than the step are covered.
        assert_eq!(seed_capture_boundary(12_320, 12_320), SeedCapture::Covered);
        assert_eq!(seed_capture_boundary(12_350, 12_320), SeedCapture::Covered);
        assert_eq!(
            seed_capture_boundary(12_320 + 8, 12_320),
            SeedCapture::Covered
        );
        // the day-16 chain: turn k+1 = 150 more ids over a restored aligned entry deepens.
        assert_eq!(
            seed_capture_boundary(12_350, 12_160),
            SeedCapture::AtBoundary(12_320)
        );
        // a legacy off-grid restored length never produces a sub-floor fed gap either.
        assert_eq!(seed_capture_boundary(12_350, 12_310), SeedCapture::Covered);
    }

